// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint8 timestamp, uint256 difficulty) public {
        vm.warp(timestamp);
        vm.roll(difficulty);

        address player = address(0x1234);
        vm.deal(player, 10);
        vm.prank(player);

        bool reverted;
        try c.play{value: 10}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
            if (random == 1) {
                assertTrue(c.pot() > 0);
            }
        }
    }
}
